Here’s a simple JavaScript function that returns a **1 MiB** string of random characters (A–Z, a–z, 0–9) using Node’s cryptographic RNG:

```js
import { randomBytes } from "node:crypto";

export function random1MiBString() {
  // 1 MiB = 1,048,576 characters
  const n = 1024 * 1024;

  // Map random bytes to a safe character set
  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
  const bytes = randomBytes(n);

  let out = "";
  out = out.padEnd(n); // pre-allocate string length (small speed win)

  // Build via array to avoid quadratic concatenation in some JS engines
  const chars = new Array(n);
  for (let i = 0; i < n; i++) chars[i] = alphabet[bytes[i] % alphabet.length];
  return chars.join("");
}
```

