```js
// write-random-logs.mjs
import { writeFile } from "node:fs/promises";
import { randomBytes } from "node:crypto";
import { join } from "node:path";

function random1MiBString() {
  const n = 1024 * 1024; // 1 MiB chars
  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
  const bytes = randomBytes(n);
  const chars = new Array(n);
  for (let i = 0; i < n; i++) chars[i] = alphabet[bytes[i] % alphabet.length];
  return chars.join("");
}

async function main() {
  const dir = new URL("./tmp/logs/", import.meta.url); // relative to this script
  let i = 0;

  while (true) {
    const data = random1MiBString();
    const name = `log-${Date.now()}-${i++}.txt`;
    await writeFile(join(dir.pathname, name), data, "utf8");
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
```

Run:
```sh
node write-random-logs.mjs
```

The loop I gave already has no cap (`while (true)`), so it will generate files indefinitely as written.

